// spec: specs/warehouse-map.md §8 · кейс .qa/tests/warehouse-map/wm-21-unplace-zero-stock-row-gone.md
// seed: tests/seed.admin.spec.ts
// #aea5d4 (עבר QA 21.10): после «הסרה מהמקום» товара с остатком 0 его строки нет в «תכולת המדף» (сразу и после обновления);
// до снятия привязанный товар с 0 виден (#d9258e0b); товар, привязанный ко второму месту, там остаётся (#7b8b97e9).
// Данные: QA-AUTO-aea5-<ts>, привязан к двум свободным полкам S1, S2 (шкаф на «קומה 1», не A–D и не G); приёмка 1 шт. в S1 →
// «החזרה לספק» 1 шт. из S1 → остаток 0 (обнуление без продажи). Журнал движений неудаляем (קליטה + החזרה לספק + ללא מקום).
// afterAll: «הסרה מהמקום» на S1/S2, удаление товара, обе полки снова «ריק».
import { test, expect, Page, Browser } from '@playwright/test';
import { auth, side, openMap } from './_helpers';

const ADMIN = auth('admin');
test.use({ storageState: ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-aea5-${TS}`;
const FLOOR = 'קומה 1';

type Shelf = { cabinet: string; name: string; code: string };
let S1: Shelf | undefined;
let S2: Shelf | undefined;
let productCreated = false;

// ---------- каталог ----------
const qtyBtn = (page: Page) => page.getByRole('button', { name: `קליטת מלאי — ${P}`, exact: true });
const locBtn = (page: Page) => page.getByRole('button', { name: `מיקום במחסן — ${P}`, exact: true });
const row = (page: Page) => qtyBtn(page).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

async function findProduct(page: Page) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(P);
  await expect(qtyBtn(page).or(page.getByText('לא נמצאו מוצרים התואמים לסינון'))).toBeVisible({ timeout: 20_000 });
}

async function createProduct(page: Page) {
  await page.goto('/catalog/new');
  await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /שם מוצר/ }).fill(P);
  await page.getByRole('textbox', { name: /מק"ט/ }).fill(`QAAEA5${TS}`);
  await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill('1');
  productCreated = true;
  await page.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });
}

/** «מיקום במחסן» (первое место) / «הוספת מיקום» (второе) → «קומה 1» → шкаф → полка → «שמירה». */
async function bind(page: Page, add: boolean, s: Shelf) {
  await findProduct(page);
  if (add) await row(page).getByText('הוספת מיקום').click();
  else await locBtn(page).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: add ? 'הוספת מיקום' : 'מיקום במחסן' })).toBeVisible();
  await dlg.getByRole('tab', { name: FLOOR }).click();
  await expect(dlg.getByText('בחרו פריט אחסון')).toBeVisible();
  await dlg.getByRole('button', { name: s.cabinet, exact: true }).first().click();
  await expect(dlg.getByText(`בחרו מדף ב«${s.cabinet}»`)).toBeVisible();
  await dlg.getByRole('button', { name: s.name, exact: true }).last().click();
  await expect(dlg).toContainText(`| ${s.code}`);
  await dlg.getByRole('button', { name: 'שמירה', exact: true }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
}

/** Приёмка qty шт. кликом по числу «במלאי» в место code. */
async function receiveInto(page: Page, qty: number, code: string) {
  await findProduct(page);
  await qtyBtn(page).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
  const select = dlg.getByRole('combobox', { name: 'מקום היעד' });
  const option = select.locator('option', { hasText: `(${code})` });
  await expect(option, `в «מקום היעד» есть ${code}`).toHaveCount(1, { timeout: 15_000 });
  await select.selectOption({ label: (await option.innerText()).trim() });
  await expect(select.locator('option:checked')).toContainText(`(${code})`);
  await dlg.getByRole('spinbutton', { name: 'כמות', exact: true }).fill(String(qty));
  await dlg.getByRole('button', { name: 'הוספה' }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
  await findProduct(page);
  await expect(qtyBtn(page)).toHaveText(String(qty), { timeout: 15_000 });
}

/** «החזרות» → «החזרה לספק» из места code, qty шт. */
async function returnFromPlace(page: Page, avail: number, code: string, qty: number) {
  await openMap(page);
  await page.getByRole('button', { name: 'החזרות' }).click();
  await page.getByRole('menuitem', { name: /^החזרה לספק/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'החזרה לספק' })).toBeVisible();
  await dlg.getByRole('textbox', { name: 'חיפוש פריט' }).fill(P);
  const box = dlg.getByRole('checkbox', { name: new RegExp(`^${P} · \\S+ זמין ${avail} · מדף ${code}`) });
  await box.check();
  await box.locator('xpath=ancestor::label[1]/parent::*').getByRole('spinbutton', { name: `כמות ל${P}` }).fill(String(qty));
  await dlg.getByRole('textbox', { name: 'לדוגמה: תנובה · תעודה 4471' }).fill(`QA-AUTO-aea5-${TS}`);
  const resp = page.waitForResponse((r) => r.url().includes('/rpc/return_to_supplier') && r.request().method() === 'POST');
  await dlg.getByRole('button', { name: 'רישום ההחזרה' }).click();
  expect((await resp).status()).toBe(200);
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
}

// ---------- карта ----------
const elementRow = (page: Page, element: string) =>
  side(page).getByRole('button', { name: new RegExp(`^${element} \\d+ `) }).first();
const placeRow = (page: Page, code: string) =>
  side(page).getByRole('button', { name: new RegExp(` ${code}(?![\\w-])`) }).first();
/** Любая строка товара в «תכולת המדף» (с кнопками или без). */
const anyItemRow = (page: Page) => side(page).getByRole('listitem').filter({ hasText: P });
const placedItem = (page: Page) => anyItemRow(page).filter({ has: page.getByRole('button', { name: 'הסרה מהמקום' }) });

const lines = async (l: ReturnType<Page['locator']>) =>
  (await l.innerText()).split('\n').map((s) => s.trim()).filter(Boolean);

async function openShelf(page: Page, s: Shelf) {
  await openMap(page, FLOOR);
  await expect(page.getByText('טוען את המלאי')).toHaveCount(0, { timeout: 30_000 });
  await elementRow(page, s.cabinet).click();
  await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
  await placeRow(page, s.code).click();
  await expect(side(page).getByRole('heading', { name: 'תכולת המדף' })).toBeVisible();
}

/** Две свободные полки «ריק» с уникальными именами в одном шкафу на «קומה 1» (не A–D и не G). */
async function pickTwoFreeShelves(page: Page): Promise<[Shelf, Shelf] | undefined> {
  await openMap(page, FLOOR);
  await expect(page.getByText('טוען את המלאי')).toHaveCount(0, { timeout: 30_000 });
  const cabinets = side(page).getByRole('button', { name: /^ארון (?![A-DG] )\S+ 0 \d+ מדפים ריק$/ });
  const names = (await cabinets.allInnerTexts()).map((t) => t.split('\n')[0].trim()).reverse();
  for (const cabinet of names) {
    await elementRow(page, cabinet).click();
    await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
    const rows = side(page).getByRole('button', { name: / [A-Z]+-\d+ ריק$/ });
    const all = await Promise.all((await rows.all()).map(lines));
    const count = new Map<string, number>();
    for (const [n] of all) count.set(n, (count.get(n) ?? 0) + 1);
    const free = all.filter(([n, c, e]) => e === 'ריק' && count.get(n) === 1 && /^[A-Z]+-\d+$/.test(c)).reverse();
    if (free.length >= 2) return [0, 1].map((i) => ({ cabinet, name: free[i][0], code: free[i][1] })) as [Shelf, Shelf];
    await side(page).getByRole('button', { name: 'כל האחסון' }).click();
  }
  return undefined;
}

async function unplace(page: Page, s: Shelf) {
  await openShelf(page, s);
  if (!(await placedItem(page).count())) return;
  await placedItem(page).getByRole('button', { name: 'הסרה מהמקום' }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'הסרת המוצר מהמקום' })).toBeVisible();
  await dlg.getByRole('button', { name: 'הסרה', exact: true }).click();
  await expect(dlg).toHaveCount(0, { timeout: 15_000 });
}

async function deleteProduct(page: Page) {
  await findProduct(page);
  if (!(await qtyBtn(page).count())) return;
  await row(page).getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible({ timeout: 20_000 });
  await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
  await expect(page.getByText(/הוסר מהקטלוג|נמחק\./).first()).toBeVisible({ timeout: 15_000 });
}

async function cleanupAll(browser: Browser) {
  const ctx = await browser.newContext({ storageState: ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  try {
    for (const s of [S1, S2]) if (s) await unplace(page, s);
    if (productCreated) await deleteProduct(page);
    for (const s of [S1, S2]) {
      if (!s) continue;
      await openMap(page, FLOOR);
      await expect(page.getByText('טוען את המלאי')).toHaveCount(0, { timeout: 30_000 });
      await elementRow(page, s.cabinet).click();
      await expect(placeRow(page, s.code), `${s.code} после уборки — «ריק»`).toHaveAccessibleName(/ריק$/);
    }
  } finally {
    await ctx.close();
  }
}

test.describe('warehouse-map — «הסרה מהמקום» של מוצר עם מלאי 0 מסירה אותו מ«תכולת המדף» (#aea5d4)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(240_000);
    await cleanupAll(browser);
  });

  test('הכנה: מוצר משויך לשני מדפים, קליטה 1 למדף הראשון והחזרה לספק → מלאי 0 #aea5d4 @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    const pair = await pickTwoFreeShelves(page);
    test.skip(!pair, 'нет шкафа с двумя свободными полками на «קומה 1» (не A–D, не G)');
    [S1, S2] = pair!;
    await createProduct(page);
    await bind(page, false, S1!);
    await bind(page, true, S2!);
    await receiveInto(page, 1, S1!.code);
    await returnFromPlace(page, 1, S1!.code, 1);
    await findProduct(page);
    await expect(qtyBtn(page)).toHaveText('0', { timeout: 15_000 });
  });

  test('לפני ההסרה: המוצר המשויך עם 0 מוצג ב«תכולת המדף» עם «העברה למיקום אחר» / «הסרה מהמקום» #aea5d4 #d9258e0b @desktop', async ({ page }) => {
    test.skip(!S1, 'нет данных из подготовки');
    await openShelf(page, S1!);
    await expect(placedItem(page)).toHaveCount(1);
    expect(await lines(placedItem(page)), 'остаток в панели — 0').toContain('0');
    await expect(placedItem(page).getByRole('button', { name: 'העברה למיקום אחר' })).toBeVisible();
  });

  test('«הסרה מהמקום» → השורה נעלמת מיד ולא חוזרת אחרי רענון; המדף «ריק»; במדף השני המוצר נשאר #aea5d4 @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    test.skip(!S1 || !S2, 'нет данных из подготовки');
    await openShelf(page, S1!);
    await placedItem(page).getByRole('button', { name: 'הסרה מהמקום' }).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'הסרת המוצר מהמקום' })).toBeVisible();
    await dlg.getByRole('button', { name: 'הסרה', exact: true }).click();
    await expect(page.getByText(/הוסר מהמקום/).first()).toBeVisible({ timeout: 15_000 });
    // строка уходит сразу (раньше висела >30 с и после F5)
    await expect(anyItemRow(page)).toHaveCount(0, { timeout: 5_000 });
    await expect(side(page).getByText('המדף ריק')).toBeVisible();

    await page.reload();
    await openShelf(page, S1!);
    await expect(anyItemRow(page)).toHaveCount(0);
    await expect(side(page).getByText('המדף ריק')).toBeVisible();
    await openMap(page, FLOOR);
    await expect(page.getByText('טוען את המלאי')).toHaveCount(0, { timeout: 30_000 });
    await elementRow(page, S1!.cabinet).click();
    await expect(side(page).getByRole('heading', { name: 'תכולת הארון' })).toBeVisible();
    await expect(placeRow(page, S1!.code)).toHaveAccessibleName(/ריק$/);

    // второе место: привязка осталась, товар с 0 виден
    await placeRow(page, S2!.code).click();
    await expect(side(page).getByRole('heading', { name: 'תכולת המדף' })).toBeVisible();
    await expect(placedItem(page)).toHaveCount(1);
    expect(await lines(placedItem(page))).toContain('0');

    // каталог: в «מיקום במחסן» осталось только S2
    await findProduct(page);
    await expect(locBtn(page)).toContainText(S2!.code);
    await expect(row(page)).not.toContainText(S1!.code);
  });
});
